{"content":"<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Paper Harbor</title>
</head>
<body>
    <h1>Welcome to Paper Harbor</h1>
    <h2>Products</h2>
    <ul id="products"></ul>
    <h2>Cart</h2>
    <ul id="cart"></ul>
    <button onclick="checkout()">Checkout</button>
    <script>
        function loadProducts() {
            fetch('products.json').then(response => response.json()).then(data => {
                const productsList = document.getElementById('products');
                data.forEach(product => {
                    const li = document.createElement('li');
                    li.textContent = `${product.name} - $${product.price} - <button onclick='addToCart("${product.name}")'>Add to Cart</button>`;
                    productsList.appendChild(li);
                });
            });
        }
        function addToCart(name) {
            fetch('cart.json', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({name: name, quantity: 1})}).then(response => response.json()).then(data => {
                loadCart();
            });
        }
        function loadCart() {
            fetch('cart.json').then(response => response.json()).then(data => {
                const cartList = document.getElementById('cart');
                cartList.innerHTML = '';
                data.forEach(item => {
                    const li = document.createElement('li');
                    li.textContent = `${item.name} - Quantity: ${item.quantity} - <button onclick='removeFromCart("${item.name}")'>Remove</button>`;
                    cartList.appendChild(li);
                });
            });
        }
        function removeFromCart(name) {
            fetch('cart.json', {method: 'DELETE', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({name: name})}).then(response => response.json()).then(data => {
                loadCart();
            });
        }
        function checkout() {
            fetch('checkout.html').then(response => response.text()).then(data => {
                document.body.innerHTML = data;
                document.getElementById('submit').onclick = function() {
                    const name = document.getElementById('name').value;
                    const email = document.getElementById('email').value;
                    fetch('checkout.json', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({name: name, email: email})}).then(response => response.json()).then(data => {
                        alert('Order confirmed!');
                        loadProducts();
                        loadCart();
                    });
                };
            });
        }
        loadProducts();
        loadCart();
    </script>
</body>
</html>","path":"PaperHarbor/index.html"}

